	createdAt: datetime("created_at").notNull().$defaultFn(() => /* @__PURE__ */ new Date()),
	/** When the collection was last updated */
	updatedAt: datetime("updated_at").notNull().$defaultFn(() => /* @__PURE__ */ new Date())
